-- Sites PV 585 W (14) et 580 W (26), puis deux projets avec liaisons et donnees additionnelles.
-- SQLite, UUID au format Doctrine : CAST(X'...' AS TEXT).
-- Idempotent : un site deja present (meme code) n'est pas recree ni renomme.
-- Les sites de ce seed sont rattaches au client CLI-TELECEL, y compris s'ils existaient deja.
-- Un projet deja present (meme code) n'est pas recree ; une liaison projet/site deja presente est ignoree.
-- Prerequis : client code CLI-TELECEL.
-- Totaux tableau 580 W : 401 panneaux. Regulateurs lus ligne a ligne = 42 (le total affiche 41).

BEGIN;

-- === Sites (insertion seulement si le code n'existe pas) ===

-- Rattache les sites deja presents (inseres sans client) a CLI-TELECEL.
UPDATE sites
SET client_id = (SELECT id FROM clients WHERE code = 'CLI-TELECEL' LIMIT 1),
    updated_at = datetime('now')
WHERE EXISTS (SELECT 1 FROM clients WHERE code = 'CLI-TELECEL')
  AND code IN (
    'BMK1101', 'BMK1121', 'BMK1138', 'KLK2184', 'KLK2191', 'KYS3222', 'KYS3223', 'KYS3228', 'KYS3229',
    'MPT6235', 'SEG4326', 'SEG4327', 'SKS5206', 'SKS5253',
    'BMK1015', 'BMK1016', 'BMK1019', 'BMK1022', 'BMK1041', 'BMK1042', 'BMK1046', 'BMK1052', 'BMK1060',
    'BMK1077', 'BMK1085', 'BMK1086', 'BMK1091', 'BMK1094', 'BMK1103', 'BMK1128', 'BMK1135', 'BMK1139',
    'BMK1143', 'BMK1164', 'BMK1165', 'BMK1171', 'BMK1182', 'BMK1318', 'KLK2183', 'SEG4252'
  );

-- === Projet panneaux 585 W (14 sites) ===

-- === Projet panneaux 580 W (26 sites, type RT/GF) ===

COMMIT;
